            var paraComments = [];
            globalCommentsList.forEach(function (gc) {
              if (gc.anchorText && plainText.indexOf(gc.anchorText) !== -1 && gc.anchorText.length > 2) {
                paraComments.push({
                  author: gc.author,
                  date: gc.date,
                  text: gc.text,
                });
              }
            });
            var additionsText = insertions.join(" ");
            var deletionsText = deletions.join(" ");
            var isDeletionOnly = insertions.length === 0 && deletions.length > 0;
            var primaryType = substantiveIns.length > 0 ? "ins" : "del";
            var primaryText =
              substantiveIns.length > 0
                ? substantiveIns[0]
                : substantiveDel.length > 0
                  ? substantiveDel[0]
                  : "[Whitespace/Formatting Change]";
            rawChanges.push({
              id: idCounter++,
              type: primaryType,
              text: primaryText,
              locateText: plainText,
              locateTerms: buildPortLocateTerms(plainText || additionsText || deletionsText),
              plainText: plainText,
              currentClauseText: plainText,
              originalClauseText: plainText,
              additionsText: additionsText,
              deletionsText: deletionsText,
              deletedText: deletionsText,
              changeSegments: combinedSegments,
              deletionOnly: isDeletionOnly,
              author:
                (
                  combinedSegments.find(function (s) {
                    return s.type === "ins" || s.type === "del";
                  }) || {}
                ).author || primaryAuthor,
              date:
                (
                  combinedSegments.find(function (s) {
                    return s.type === "ins" || s.type === "del";
                  }) || {}
                ).date || "",
              revisionAuthors: authorsList,
              sourceParagraphIndex: data.index,
              sourceTypeOrdinal: 0,
              _anchorName: pName,
              counterpartyComments: paraComments,
              counterpartyCommentCount: paraComments.length,
              hasRevision: true,
            });
          }
        }
        // ─── Anchor-all-paragraphs pass ───────────────────────────────────────
        // For every paragraph WITHOUT substantive tracked changes, add a stub row
        // with hasRevision:false so section grouping can include it. Sidebar render
        // filters by hasRevision so unchanged paragraphs stay invisible there;
        // they only matter for grouping (and the diagnostic). Bookmark them too so
        // cursor-snap can locate them.
        var __changedIdxSet = {};
        rawChanges.forEach(function (r) {
          if (typeof r.sourceParagraphIndex === "number") __changedIdxSet[r.sourceParagraphIndex] = true;
        });
        var __extractPlainTextFromParaXml = function (xml) {
          // Strip paragraph-properties and run-properties FIRST. They contain
          // <w:tabs>, <w:left>, <w:tblPr>, <w:type>, etc. — none of which is body
          // text, all of which would otherwise sneak past a too-greedy <w:t...>
          // regex match. Same approach as parseOoxmlToSegments above.
          var clean = String(xml || "")
            .replace(/<w:pPr>[\s\S]*?<\/w:pPr>/g, "")
            .replace(/<w:rPr>[\s\S]*?<\/w:rPr>/g, "");
          // \b after w:t prevents matching <w:tabs>, <w:tblPr>, <w:type>, etc.
          var rg = /<w:t\b(?:\s[^>]*)?>([\s\S]*?)<\/w:t>/g;
          var out = "";
          var m;
          while ((m = rg.exec(clean)) !== null) out += m[1];
          return out
            .replace(/&amp;/g, "&")
            .replace(/&lt;/g, "<")
            .replace(/&gt;/g, ">")
            .replace(/&quot;/g, '"')
            .replace(/&apos;/g, "'");
        };
        for (var __upi = 0; __upi < __paragraphXmls.length; __upi++) {
          if (__changedIdxSet[__upi]) continue;
          var __upara = paragraphs.items[__upi];
          if (!__upara) continue;
          var __upName = "_ELI_P_" + __upi;
          var __uPlainText = normalizePortWhitespace(__extractPlainTextFromParaXml(__paragraphXmls[__upi]));
          if (!__uPlainText) continue; // skip purely empty paragraphs
          __upara.getRange().insertBookmark(__upName);
          rawChanges.push({
            id: idCounter++,
            type: "no-change",
            text: "",
            locateText: __uPlainText,
            locateTerms: buildPortLocateTerms(__uPlainText),
            plainText: __uPlainText,
            currentClauseText: __uPlainText,
            originalClauseText: __uPlainText,
            additionsText: "",
            deletionsText: "",
            deletedText: "",
            changeSegments: [],
            deletionOnly: false,
            author: "",
            date: "",
            revisionAuthors: [],
            sourceParagraphIndex: __upi,
            sourceTypeOrdinal: 0,
            _anchorName: __upName,
            counterpartyComments: [],
            counterpartyCommentCount: 0,
            hasRevision: false,
          });
        }
        // Keep rawChanges in document order (paragraph index ascending) so the
        // sidebar's flat numbered list reflects document flow when filtered.
        rawChanges.sort(function (a, b) {
          return (Number(a.sourceParagraphIndex) || 0) - (Number(b.sourceParagraphIndex) || 0);
        });
        await context.sync();
      });
      // rawChanges now includes unchanged paragraphs (hasRevision:false) for grouping —
      // count revisioned rows for the "no tracked changes" guard.
      var __revisionCount = rawChanges.filter(function (r) { return r && r.hasRevision === true; }).length;
      if (__revisionCount === 0) {
        showTrackPortPlaceholder("No tracked changes found. Turn on Track Changes and make edits first.");
        return;
      }
      // (Section-number extraction removed — sidebar now shows a flat numbered list of
      //  changes, not section IDs. Each rawChange already has _anchorName for jump-to.)
      var session = {
        mode: "port-shell",
        capturedAt: new Date().toISOString(),
        captureId: String(Date.now()) + "-" + Math.random().toString(36).slice(2),
        rawChanges: rawChanges,
        metrics: null,
        analysis: null,
      };
      // Pre-populate _redlineBaseline with the body OOXML snapshot. Collect Redlines
      // diffs this against current body OOXML to show "what changed during the session"
      // — including redline structure (ins/del), not just plain text.
      session._redlineBaseline = {
        capturedAt: Date.now(),
        bodyOoxml: baselineBodyOoxml,
        totalChanges: rawChanges.length,
      };
      session._userActions = [];
      var detectedDocType = window._eliDisablePlaybookForReview ? "" : window._eliDocType || "";
      var autoPlaybook = detectedDocType ? await window._getPlaybookForType(detectedDocType) : null;
      var mapping =
        window.TrackChangesPort && typeof window.TrackChangesPort.getClauseMapping === "function"
          ? window.TrackChangesPort.getClauseMapping()
          : null;
      if (window._eliDisablePlaybookForReview) {
        mapping = null;
        session._autoSelectedPlaybook = "";
        if (window.TrackChangesPort && typeof window.TrackChangesPort.setClauseMapping === "function")
          window.TrackChangesPort.setClauseMapping(null);
      } else if (!mapping || !mapping.clauses || mapping.clauses.length === 0) {
        if (autoPlaybook && autoPlaybook.clauseMapping) {
          mapping = autoPlaybook.clauseMapping;
          if (window.TrackChangesPort && typeof window.TrackChangesPort.setClauseMapping === "function")
            window.TrackChangesPort.setClauseMapping(mapping);
        }
      }
      if (!window._eliDisablePlaybookForReview && autoPlaybook) {
        session._autoSelectedPlaybook = autoPlaybook.id || autoPlaybook.type || detectedDocType;
      }
      session.clauseMapping = mapping || { libraryName: "", clauses: [], articleGuidance: {} };
      // Map every paragraph (changed and unchanged) against the playbook so
      // grouping is correct. Cost: rows × clauses fuzzy comparisons. Slower than
      // changed-only but the user explicitly wants this — accuracy of section
      // grouping over scan speed. The AI-side filter (sectionClauses.filter +
      // Risk Scan hasRevision skip) keeps unchanged paragraphs out of prompts.
      session.rawChanges = applyClauseMappingToPortChanges(session.rawChanges, session.clauseMapping);
      session.rawChanges.forEach(function (row) {
        row.aiPayload = buildPortAiPayloadFromChange(row, session.clauseMapping);
      });
      session.grouped = buildPortArticleSectionGroups(session.rawChanges);
      session.groupedAi = buildPortSectionsForAi(session.rawChanges, session.clauseMapping);
      window.TrackChangesPort.setSession(session);
      var allAuthorsList = Object.keys(allUniqueAuthors);
      window.promptTrackPortAuthorsDialog(allAuthorsList, session, function () {
        var aiDisabled = false;
        try {
          aiDisabled = !!(
            window.TrackChangesPort &&
            typeof window.TrackChangesPort.getDisableAiOnAnalyze === "function" &&
            window.TrackChangesPort.getDisableAiOnAnalyze()
          );
        } catch (_) { }
        if (!aiDisabled && typeof window.runTrackChangesAiFromSession === "function") {
          window.runTrackChangesAiFromSession(btn);
        } else {
          if (typeof window.renderTrackPortWorkbench === "function") {
            window.renderTrackPortWorkbench(session);
          }
        }
        if (btn) btn.disabled = false;
        setLoading(false);
        if (window.eli && window.eli.activity && typeof window.eli.activity.add === "function") {
          window.eli.activity.add({
            type: "review-redline",
            icon: "📝",
            label: "Review Redline",
            summary:
              session.rawChanges.length +
              " substantive change" +
              (session.rawChanges.length === 1 ? "" : "s") +
              " captured",
            payload: session,
            restoreFn: function (payload) {
              if (typeof window.showLegalReview === "function") window.showLegalReview();
              if (window.TrackChangesPort && typeof window.TrackChangesPort.setSession === "function") {
                window.TrackChangesPort.setSession(payload);
              }
              if (typeof window.renderTrackPortWorkbench === "function") {
                window.renderTrackPortWorkbench(payload);
              }
            },
          });
        }
      });
    } catch (e) {
      if (typeof ELI_DEBUG !== "undefined" && ELI_DEBUG) console.error("runRedlineSummary error:", e);
      showTrackPortPlaceholder("Error executing Final 2 Anchors mapping: " + e.message);
      if (btn) btn.disabled = false;
      setLoading(false);
    }
  };
  window.runTrackChangesAiFromSession = function (btn) {
    return runPortAdapterAi(window.TrackChangesPort.getSession(), btn);
  };
  window.locateTrackedChange = function (index) {
    if (typeof showToast === "function") showToast("Locate triggered! " + index, "info");
    var adapter = window.TrackChangesPort.getAdapter();
    if (adapter && typeof adapter.locate === "function") {
      return adapter.locate(index, window.TrackChangesPort.getSession());
    }
    return locatePortRowByIndex(index, window.TrackChangesPort.getSession());
  };
}

jsonTools.init:
function init(eli) {
  if (!eli.events) eli.events = { guard: function (fn) { return fn; }, safeAsync: function (p) { return p; } };

  // Boot the v2 module (registers ~30 window globals on first call).
  if (typeof window._eliBootReviewRedlines === "function") {
    try { window._eliBootReviewRedlines(); }
    catch (e) {
      eli.log.event("tool", "review_redlines_boot_failed", { msg: e && e.message });
      return;
    }
  } else {
    eli.log.event("tool", "review_redlines_boot_missing", {});
    return;
  }

  // ─── Tile handler ────────────────────────────────────────────────
  function _open() {
    if (!eli.ai || typeof eli.ai.hasApiKey !== "function" || !eli.ai.hasApiKey()) {
      if (typeof showToast === "function") showToast("Set a Gemini API key in Settings → Global first.", "warn");
      if (eli.settings && typeof eli.settings.show === "function") eli.settings.show();
      return;
    }
    try { if (eli.stats && eli.stats.record) eli.stats.record("appOpenedReviewRedlines"); } catch (e) {}
    if (typeof window.runRedlineSummary !== "function") {
      if (typeof showToast === "function") showToast("Review Redlines failed to load.", "err");
      return;
    }
    try { window.runRedlineSummary(); }
    catch (e) {
      eli.log.event("tool", "review_redlines_launch_failed", { msg: e && e.message });
      if (typeof showToast === "function") showToast("Review Redlines failed: " + (e.message || "unknown"), "err");
    }
  }

  eli.register({
    tile: { app_review_redlines: _open },
    // Programmatic launch for cross-tool callers (compare's runVersionCompare
    // dispatches into Review Redlines after a deep-diff finishes).
    review_redlines: { open: _open, run: _open },
    // Activity restore — v2 activity entries use "review-redline" /
    // "trackport". Match both.
    activity_restore: {
      "review-redline": function () { _open(); },
      "review_redlines":  function () { _open(); },
      "trackport":       function () { _open(); },
    },
  });

  // ─── Activity-feed entry on launch ───────────────────────────────
  if (eli.activity && typeof eli.activity.add === "function") {
    var prev = _open;
    _open = function () {
      try {
        eli.activity.add({
          type: "review-redline",
          icon: "📝",
          label: "Review Redlines",
          summary: "Opened Track-Port workbench",
          payload: { ts: Date.now() },
          restoreChannel: "activity_restore",
          restoreKey: "review-redline",
        });
      } catch (e) {}
      return prev();
    };
  }

  eli.log.event("tool", "review_redlines_initialized", {});
}

jsonTools.css:
/* tools/review_redlines/style.css
 * Track-Port (Review Redlines) panel styles.
 * The v2 module renders with inline styles for almost everything; this
 * file only provides the handful of class-based hooks that v2 also used
 * via taskpane.css. Most rules are scoped to `#tpFocusShell`.
 */

/* Status badge in the focus-shell header — flips through "ready" /
 * "scanning" / "waiting on AI" states; kept as a class so the v2 code's
 * `setTrackPortStatus(msg)` (which writes to a DOM element by id) can
 * style it consistently. */
.tpStatusReady    { color: #2e7d32; }
.tpStatusScanning { color: #1565c0; }
.tpStatusError    { color: #c62828; }

/* Section dropdown chevron flips when the section is expanded. */
.tpSectionChevron { transition: transform 0.18s; display: inline-block; }
.tpSectionChevron._open { transform: rotate(90deg); }

/* Per-row buttons (Accept / Reject / Fallback / Locate) — neutral
 * platinum pills, color flips when locked-in. */
.tpPbSwitchBtn,
.tpSetAttEmail,
.tpSetPbDelete,
.tpSetPbEdit {
  font: 700 11px/1 'Inter', sans-serif;
  padding: 6px 10px;
  background: linear-gradient(to bottom, #f7f9fa 0%, #dce3e8 100%);
  color: #455a64;
  border: 1px solid #b0bec5;
  cursor: pointer;
  transition: all 0.12s;
}
.tpPbSwitchBtn:hover,
.tpSetAttEmail:hover,
.tpSetPbEdit:hover { background: linear-gradient(to bottom, #fff 0%, #e3f2fd 100%); color: #1565c0; border-color: #90caf9; }
.tpSetPbDelete:hover { background: #fef2f2; color: #b91c1c; border-color: #fca5a5; }
